def is_valid_aba_routing_number(s):
    if len(s) != 9 or not s.isdigit():
        return False
    d = [int(c) for c in s]
    total = 3*(d[0]+d[3]+d[6]) + 7*(d[1]+d[4]+d[7]) + 1*(d[2]+d[5]+d[8])
    return total % 10 == 0

def is_valid_serial_checksum(s):
    alphabet = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'
    if len(s) != 8 or not all(c in alphabet for c in s):
        return False
    if not s[7].isdigit():
        return False
    total = sum(alphabet.index(c) for c in s[:7])
    return str(total % 10) == s[7]

