def is_valid_simple_url(s):
    if ' ' in s:
        return False
    rest = None
    for prefix in ('http://', 'https://'):
        if s.startswith(prefix):
            rest = s[len(prefix):]
            break
    if rest is None or not rest:
        return False
    slash_idx = rest.find('/')
    domain = rest if slash_idx == -1 else rest[:slash_idx]
    if not domain:
        return False
    labels = domain.split('.')
    if len(labels) < 2:
        return False
    for label in labels:
        if not label or label.startswith('-') or label.endswith('-'):
            return False
        if not all(c.isalnum() or c == '-' for c in label):
            return False
    tld = labels[-1]
    return tld.isalpha() and len(tld) >= 2

def is_valid_slug(s):
    if not s or s[0] == '-' or s[-1] == '-' or '--' in s:
        return False
    return all(c.isdigit() or c == '-' or (c.isalpha() and c.islower()) for c in s)

def is_valid_domain_name(s):
    labels = s.split('.')
    if len(labels) < 2:
        return False
    for label in labels:
        if not (1 <= len(label) <= 63):
            return False
        if label.startswith('-') or label.endswith('-'):
            return False
        if not all(c.isalnum() or c == '-' for c in label):
            return False
    return labels[-1].isalpha() and len(labels[-1]) >= 2

def is_valid_file_name(s, allowed_exts):
