def is_valid_query_string(s):
    if not s.startswith('?') or len(s) < 2:
        return False
    body = s[1:]
    pairs = body.split('&')
    for p in pairs:
        if p.count('=') != 1:
            return False
        k, v = p.split('=')
        if not k or not v or not k.isalnum() or not v.isalnum():
            return False
    return True

def is_valid_relative_path(s):
    if not s or s.startswith('/') or s.endswith('/'):
        return False
    segments = s.split('/')
    for seg in segments:
        if not seg or seg in ('.', '..'):
            return False
        if not all(c.isalnum() or c in '_-.' for c in seg):
            return False
    return True

def is_valid_non_blocked_email(s, blocked_domains):
    if s.count('@') != 1:
        return False
    local, domain = s.split('@')
    if not local or '.' not in domain:
        return False
    if not all(c.isalnum() or c in '._+-' for c in local):
        return False
    labels = domain.split('.')
    for label in labels:
        if not label or not all(c.isalnum() or c == '-' for c in label):
            return False
    blocked_lower = {d.lower() for d in blocked_domains}
    return domain.lower() not in blocked_lower

def is_valid_markdown_link(s):
    import re
    m = re.fullmatch(r'\[([^\]]+)\]\((\S+)\)', s)
    if not m:
        return False
    url = m.group(2)
    return url.startswith('http://') or url.startswith('https://')

