def is_valid_ipv4_address(s):
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for p in parts:
        if not p.isdigit():
            return False
        if len(p) > 1 and p[0] == '0':
            return False
        if int(p) > 255:
            return False
    return True

def is_valid_ipv4_cidr(s):
    if s.count('/') != 1:
        return False
    ip, prefix = s.split('/')
    parts = ip.split('.')
    if len(parts) != 4:
        return False
    for p in parts:
        if not p.isdigit():
            return False
        if len(p) > 1 and p[0] == '0':
            return False
        if int(p) > 255:
            return False
    if not prefix.isdigit():
        return False
    if len(prefix) > 1 and prefix[0] == '0':
        return False
    return 0 <= int(prefix) <= 32

def is_valid_ipv6_full(s):
    groups = s.split(':')
    if len(groups) != 8:
        return False
    hexdigits = set('0123456789abcdefABCDEF')
    for g in groups:
        if not (1 <= len(g) <= 4):
            return False
        if not all(c in hexdigits for c in g):
            return False
    return True
